curl -X POST "https://your-shop-url.com/api/v4/api-keys/" \
  -H "Authorization: Api-Key {{API_KEY}}" \
  -H "Content-Type: application/json" \
  -d '{
  "name": "My API Key"
}'

curl -X POST "https://your-shop-url.com/api/v4/order-process/{order_id}/events/" \
  -H "Authorization: Api-Key {{API_KEY}}" \
  -H "Content-Type: application/json" \
  -d '{
  "text": "با مشتری تماس گرفته شد."
}'
